INSERT INTO site_entries (kind, title, subtitle, body, sort_order) VALUES
  ('service', 'New construction', '', 'Ground-up buildings — structure, envelope, and the rooms inside — run as one contract from first set-out to handover.', 0),
  ('service', 'Interiors & fit-out', '', 'Joinery, finishes, and services coordinated so the last room is as considered as the first slab.', 1),
  ('service', 'Structural works', '', 'Frames, foundations, and alterations handled with the engineer in the room, not after the fact.', 2),
  ('service', 'Restoration', '', 'Older fabric kept honest. We repair what should stay and replace only what has failed.', 3),
  ('service', 'Site coordination', '', 'Trades sequenced on a live site. One superintendent, one programme, no competing stories.', 4),
  ('service', 'Project leadership', '', 'Cost, programme, and quality held in the same hand from briefing through defects.', 5),
  ('step', 'Brief', '01', 'We walk the plot, read the constraints, and write down what the building must actually do.', 0),
  ('step', 'Plan', '02', 'Drawings, method, and a programme that the site can keep. No theatre — a buildable set.', 1),
  ('step', 'Build', '03', 'The same people who planned it stay on site. Structure first, then the work you can touch.', 2),
  ('step', 'Handover', '04', 'Snag, document, and leave the keys with a building that is ready to be lived in.', 3);
